# frozen_string_literal: true

# Generated by Torque Lift. Do not edit: Torque Lift regenerates it from torque-lift/tracking-plan.yaml.

# Checks that the Torque Lift server wrapper sends what the tracking plan says. Nothing leaves the
# machine: the collector call is replaced.
require "test_helper"

class TorqueLiftAnalyticsTest < ActiveSupport::TestCase
  KEY = "test-server-key"
  HOST = "https://collector.example.test"
  ENV_SET = { "TORQUELIFT_JITSU_SERVER_KEY" => KEY, "TORQUELIFT_JITSU_HOST" => HOST }.freeze
  CALLS = [
    ["Ticket Replied", :ticket_replied, { ticket_id: "id_fire_test" }, {"ticket_id" => "id_fire_test"}]
  ].freeze

  FakeRequest = Struct.new(:cookies)
  FakeResponse = Struct.new(:code)

  class FakeHttp
    attr_reader :posted
    attr_accessor :use_ssl, :open_timeout, :read_timeout

    def initialize(fail_with: nil)
      @posted = []
      @fail_with = fail_with
    end

    def request(post)
      raise @fail_with if @fail_with

      @posted << post
      FakeResponse.new("200")
    end
  end

  # Replaces a singleton method for the block, then puts it back.
  def with_stub(target, name, replacement)
    original = target.method(name)
    target.singleton_class.send(:define_method, name) { |*args, &block| replacement.call(*args, &block) }
    yield
  ensure
    target.singleton_class.send(:define_method, name, original)
  end

  def with_env(values)
    saved = ENV.to_h
    ENV.replace(saved.reject { |name, _| name.start_with?("TORQUELIFT_") }.merge(values))
    yield
  ensure
    ENV.replace(saved)
  end

  def deliver(function, http: FakeHttp.new, request: FakeRequest.new({}), env: ENV_SET, **kwargs)
    with_env(env) do
      with_stub(Net::HTTP, :new, ->(*) { http }) do
        with_stub(TorqueLift::Analytics, :background, ->(*, &block) { block.call }) do
          TorqueLift::Analytics.public_send(function, request: request, user_id: "user_1", message_id: "msg_1", **kwargs)
        end
      end
    end
    http.posted
  end

  test "each event sends its plan properties" do
    CALLS.each do |name, function, arguments, properties|
      posted = deliver(function, **arguments)
      assert_equal 1, posted.size, name
      assert_equal "/api/s/s2s/track", posted.first.path
      assert_equal KEY, posted.first["X-Write-Key"]
      body = JSON.parse(posted.first.body)
      assert_equal "track", body["type"]
      assert_equal name, body["event"]
      assert_equal "user_1", body["userId"]
      assert_equal "msg_1", body["messageId"]
      assert_equal properties.merge(TorqueLift::GLOBAL_PROPERTIES), body["properties"]
      assert_equal TorqueLift::GLOBAL_CONTEXT["app"], body["context"]["app"]
      assert_not body.key?("anonymousId")
    end
  end

  test "the consenting visitors anonymous id rides along" do
    _name, function, arguments, _properties = CALLS.first
    request = FakeRequest.new({ TorqueLift::Analytics::COOKIE => "anon_1" })
    body = JSON.parse(deliver(function, request: request, **arguments).first.body)
    assert_equal "anon_1", body["anonymousId"]
  end

  test "nothing is sent without the key or the host" do
    _name, function, arguments, _properties = CALLS.first
    [{}, { "TORQUELIFT_JITSU_SERVER_KEY" => KEY }, { "TORQUELIFT_JITSU_HOST" => HOST }].each do |env|
      assert_empty deliver(function, env: env, **arguments)
    end
  end

  test "a failing collector never raises into the caller" do
    _name, function, arguments, _properties = CALLS.first
    assert_empty deliver(function, http: FakeHttp.new(fail_with: IOError.new("down")), **arguments)
  end

  test "a route template names the page, not the url" do
    assert_equal "/projects/[id]", TorqueLift.route_template("/projects/:id(.:format)")
    assert_equal "/files/[...path]", TorqueLift.route_template("/files/*path(.:format)")
    assert_equal "/", TorqueLift.route_template("/")
    assert_nil TorqueLift.route_template("(/:locale)/projects")
    assert_nil TorqueLift.route_template(nil)
  end
end
